// #2: "b"                 queue: есть
// #3: объект эффекта {tag, create, deps, inst, next}
// узла для useContext нет

let currentFiber = null; // fiber, который сейчас рендерится
let cursor = null;       // текущий узел в его списке хуков
let isMount = false;

function render(fiber) {
  currentFiber = fiber;
  isMount = fiber.memoizedState === null; // хуков ещё нет: первый рендер
  cursor = null;
  fiber.output = fiber.type(fiber.props);  // вызвать компонент
}

function nextHook() {
  if (isMount) {
    const hook = { memoizedState: undefined, queue: [], next: null };
    if (cursor === null) currentFiber.memoizedState = hook; // первый хук
    else cursor.next = hook;                                 // в конец списка
    cursor = hook;
  } else {
    cursor = cursor === null ? currentFiber.memoizedState : cursor.next;
    if (cursor === null)
      throw new Error('Rendered more hooks than during the previous render.');
  }
  return cursor;
}

function useState(initial) {
  const hook = nextHook();
  if (isMount) {
    hook.memoizedState = typeof initial === 'function' ? initial() : initial;
    const fiber = currentFiber;     // привязка один раз: setState стабилен
    hook.dispatch = (action) => {
      hook.queue.push(action);      // 1. положить в очередь
      scheduleRender(fiber);        // 2. запланировать, а не рендерить сразу
    };
  }
  let state = hook.memoizedState;   // 3. на рендере применить очередь по порядку
  for (const action of hook.queue)
    state = typeof action === 'function' ? action(state) : action;
  hook.queue = [];
  hook.memoizedState = state;
  return [state, hook.dispatch];
}

